const MMR_TRAIT_RULES = {
  "Abrasive": {"effect":"The character rubs people the wrong way. This gives them trouble when trying to make Ego checks to persuade someone to help them out. It gives them an edge when they're trying to make Ego checks to intimidate someone.","page":59},
  "Anathema": {"effect":"The character suffers direct harm when exposed to a particular substance. They cannot voluntarily enter the same space with it. If they are touched by it, they instantly suffer the damage of a Rank 3 attack roll that automatically succeeds. This continues each turn until they are separated from the substance or are killed or destroyed. Damage caused by Anathema ignores all damage reduction the character has and cannot be healed by their Healing Factor.","page":59},
  "Audience": {"effect":"Many people follow the character's work and treat them with the respect they deserve. By making an Ego check, the character can persuade their audience to provide help in the form of information or resources. The Narrator determines the TN of the Ego check based on the favor requested.","page":59},
  "Battle Ready": {"effect":"The character is always mentally prepared for any sort of trouble to start. Add+30 Focus.","page":59},
  "Beguiling": {"effect":"The character has an edge when making an Ego check to persuade someone who could be attracted to them.","page":59},
  "Berserker": {"effect":"The character often loses control of their temper. Any time they take physical damage, they must make an Ego check with a TN equal to the amount of damage done. If they fail, they go berserk and must charge at full speed into combat with the enemy who hurt them. Being berserk gives the character an edge on all close attacks and adds +2 to their Melee, Resilience and Ego defenses. However, it takes -2 from their Agility defense, and they cannot use ranged weapons.\n\nIf the character defeats the enemy who hurt them, they must then charge to attack the next closest foe. At the end of the character's turn, they lose 5 Focus. When their Focus is reduced to the point that the character could not voluntarily spend any more Focus—or if there are no enemies in sight—the berserk state automatically ends.","page":59},
  "Big": {"effect":"The character's size is big, which applies -1 to their Melee and Agility defenses, adds +1 to their Run Speed, and increases their reach to 2. They still occupy a single space.","page":60},
  "Bloodthirsty": {"effect":"The character likes hurting people—even killing them. After they knock someone unconscious, they must make a Challenging Ego check to keep from continuing to attack them until they're dead. A character with this trait cannot take the Heroic tag.","page":60},
  "Breathe Different": {"effect":"The character cannot breathe Earth's air for long. They lose1 point of Health for every minute they do not have some sort of assistance to allow them to breathe properly.","page":60},
  "Clinician": {"effect":"The character has an edge on Logic checks to determine what is medically wrong with someone they examine.","page":60},
  "Clueless": {"effect":"The character tends to shut out things they're not entirely focused on. They have trouble on any Vigilance checks to spot hidden or invisible things. Enemies have an edge on Agility checks to sneak near or past them.","page":60},
  "Combat Expert": {"effect":"The character knows how to handle themselves better than most. They have an edge on Melee attacks against enemies of Rank 1.","page":60},
  "Combat Reflexes": {"effect":"The character can react quickly in combat. This grants them one additional reaction each turn.","page":60},
  "Connections": {"effect":"The character knows someone with access to and knowledge of a particular field. The connection could be a reporter, a police officer, a politician, a mobster and so on. By making an Ego check, the character can call on their contact to provide help in the form of clues, information or resources. The Narrator determines the TN of the Ego check based on the favor requested. This trait can be selected multiple times, using many different types. These include Celebrities, Community, Criminal, Espionage, Military, Outsiders, Police, Professional, Sources, Super Heroes and so on.","page":60},
  "Dealmaker": {"effect":"The character is skilled at the art of negotiation. They have an edge on action checks that have to do with making deals.","page":60},
  "Determination": {"effect":"The character never gives up, even when they feel like they're at their worst. While demoralized, they do not gain trouble on all actions, though they still cannot maintain concentration or spend further Focus.","page":60},
  "Eidetic Memory": {"effect":"The character rarely forgets anything. If their player forgets something, they can ask the Narrator to remind them.","page":60},
  "Enduring Constitution": {"effect":"The character can function for up to 48 hours without sleep and has an edge on Resilience checks to overcome fatigue or weariness.","page":60},
  "Enhanced Physique": {"effect":"The character is stronger than regular humans. Treat them as one size bigger for lifting, carrying, swinging and throwing things. (This does not stack with other factors.)","page":60},
  "Extra Occupation": {"effect":"The character has a busy life and has done all sorts of things. They can choose another occupation.","page":60},
  "Extraordinary Origin": {"effect":"The character has an additional origin. This trait can be selected multiple times, but each time must be cleared with the Narrator. Take care to make sure that the origins make some kind of sense when combined together.","page":60},
  "Famous": {"effect":"The character is widely known—at least among a certain group of people or a population. They may be well-liked or they may be hated, but either way, they are famous. They have an edge when making an Ego check to persuade someone who thinks favorably of them. They have trouble when making an Ego check to persuade someone who dislikes them. If the character has a secret identity, this trait works for only one of their identities. However, it can be taken multiple times for multiple identities..","page":60},
  "Fearless": {"effect":"The character is extremely brave. They have an edge on any action checks required to deal with fear.","page":60},
  "First Aid": {"effect":"The character knows how to administer first aid. They have an edge on Logic checks to stop bleeding.","page":60},
  "Font of Information": {"effect":"The character has an edge on Logic checks having to do with knowledge.","page":60},
  "Free Running": {"effect":"The character has an edge on Agility checks made to perform acrobatics during a movement action.","page":60},
  "Fresh Eyes": {"effect":"The character has their own way of doing things. This often makes them seem strange to those around them, but it means they can bring new perspectives to existing issues. They have an edge on Logic checks when faced with something for the first time.","page":61},
  "Gearhead": {"effect":"The character knows their way around machines. They have an edge on Logic checks to figure out how any machine works.","page":61},
  "Glibness": {"effect":"The character can strike up a conversation with anyone at any time and can often convince them to lend a hand. They have an edge on Ego checks to persuade characters they are speaking to for the first time.","page":61},
  "God Heritage": {"effect":"The character—or at least one of their ancestors—is a god. Pick something that they are the god of. They don't have to be a god that most people have heard of. In fact, they can be the god of something entirely new. However, they cannot generally be the god of something that's already been claimed by someone else in their pantheon. Other gods are often jealous of their positions and take issue with such rivals. The character has an edge when dealing with something that they are the god of.\n\nRestriction: This trait can be selected only by characters with a mythic origin and an attachment to a particular pantheon, like Asgardian or Olympian.","page":61},
  "Gullible": {"effect":"The character is easy to fool. People lying to them have an edge on their Ego checks to persuade the character of something.","page":61},
  "Honest": {"effect":"The character is a terrible liar. They have trouble any time they make an Ego check that involves telling a lie. However, they have an edge on any friendly Ego (persuasion) checks in which they're truthful.","page":61},
  "Interrogation": {"effect":"The character knows how to ask the right questions in the right way. They have an edge on Ego or Logic checks made when asking questions.","page":62},
  "Inventor": {"effect":"The character is good at coming up with solutions on the fly. They have an edge on Logic checks when creating or repairing things.","page":62},
  "Investigation": {"effect":"The character is an expert investigator. They have an edge on Vigilance checks to spot clues and on Logic checks related to interpreting clues. If they have access to a forensics lab at the time, they gain a second edge on such checks.","page":62},
  "Iron Will": {"effect":"Enemies have trouble on Ego attacks to control the character's mind or influence their behavior. Also, the character gains an edge on Ego checks to break free of mind control or other compulsions.","page":62},
  "Legal Eagle": {"effect":"The character knows the laws of their homeland and can help others navigate them. They have an edge on Logic checks when dealing with legalities.","page":62},
  "Leverage": {"effect":"The character is good at figuring out what people want and using it against them. They have an edge on Logic checks to investigate people and on Ego checks to persuade people they've investigated.","page":62},
  "Loner": {"effect":"The character does not play well with others. They cannot be given an edge via assistance by someone who is not a teammate.","page":62},
  "Monster": {"effect":"The character is some kind of monster, often of a type spoken of in legend. They have an edge whenever they attempt to intimidate someone.","page":62},
  "Out of Shape": {"effect":"The character is in poor physical condition. They are considered one size smaller for the purposes of lifting, carrying, swinging and throwing things.","page":62},
  "Piloting": {"effect":"The character knows how to operate vehicles of all kinds. They have an edge on Agility checks triggered when piloting or driving a vehicle during a movement action. This applies to cars, boats, aircraft and so on.","page":62},
  "Presence": {"effect":"The character knows how to command attention on demand. They have an edge on Ego checks that involve getting people to pay attention to them or to voluntarily do things for them.","page":62},
  "Public Speaking": {"effect":"The character knows how to get the attention of a crowd, whether that's at a political rally or in front of a jury or a classroom. They have an edge on Ego checks when attempting to persuade groups.","page":62},
  "Pundit": {"effect":"The character knows how to break news items and put them into context to craft a story around them. They have an edge on Ego or Logic rolls made when giving their opinion via media.","page":62},
  "Quick Learner": {"effect":"If the character fails an action check, they gain an edge on the check if they try the same action again on their next turn.","page":62},
  "Scientific Expertise": {"effect":"The character has extensive scientific training. They have an edge on Logic checks made when dealing with scientific research. If they have access to an appropriate lab at the time, they gain a second edge on such checks.","page":62},
  "Signature Attack": {"effect":"The character is known for favoring a particular kind of weapon or attack power. They have an edge when making attacks that way. This trait can be taken more than once, but each time must be with a different kind of weapon or attack power.","page":62},
  "Situational Awareness": {"effect":"The character is trained to always keep an eye out for trouble. They have an edge on initiative checks.","page":62},
  "Skeptical": {"effect":"The character is hard to fool. People lying to them have trouble on their Ego checks to persuade the character of something.","page":62},
  "Small": {"effect":"The character's size is small, which adds +1 to their Melee and Agility defenses and takes -1 from their Run Speed.","page":62},
  "Sneaky": {"effect":"The character has an edge on Agility checks when sneaking around. Enemies have trouble on Vigilance checks to detect the character when the character is invisible or hiding.","page":62},
  "Stranger": {"effect":"The character doesn't understand local customs. They have trouble on checks made when trying to decipher such things or when trying to pass themselves off as a local.","page":62},
  "Surprising Power": {"effect":"The character can choose a power they normally wouldn't be able to use. The character will still need to have any prerequisite powers, but they can ignore rank and origin requirements. This trait can be selected multiple times.","page":62},
  "Tech Reliance": {"effect":"The character relies on technology for powers. When they take damage that would render them unconscious, they can instead choose to lose all of their technology-related powers and remain conscious with 1 point of Health remaining. Assuming the character has access to parts and tools, lost powers can be repaired after a battle.","page":62},
  "Weakness": {"effect":"The character suffers an unusual amount of harm from certain substances. Any attack made with that substance ignores all inherent damage reduction the character has and cannot be healed by their Healing Factor.","page":63},
  "Weird": {"effect":"The character has something weird (or even wonderful) about them. This causes people to have strong reactions to them, both good and bad. They have an edge on all Ego checks to persuade people inclined to like them and trouble on all Ego checks against people inclined to dislike them.","page":63},
};

const MMR_TAG_RULES = {
  "A.I.": {"effect":"The character possesses an artificial intelligence in a computerized mind. Their digital nature means that copies or backups can be made of their mind and can even be transferred into other compatible forms.","page":63},
  "Alien Heritage": {"effect":"The character—or at least one of their ancestors—is not from Earth. Pick an alien race that they belong to. If they were not raised on Earth, they should consider taking the Outsider occupation.","page":63},
  "Alternate Form": {"effect":"The character can change from their regular human form into another form and back. When in either form, the character can only access powers assigned to that form. In most cases, this means that the character can use powers only when in their alternate form. This tag applies to characters that switch from one humanoid form to another, like Colossus, Emma Frost and many of the Hulks. It also applies to characters that have inhuman forms, like werewolves and vampires.","page":63},
  "Amphibious": {"effect":"The character can breathe just fine underwater and can see and hear well in it too.","page":63},
  "Auditory Issues": {"effect":"The character has trouble hearing that can range from partial to full deafness.","page":63},
  "Authority": {"effect":"The character has a legal authority of some kind. They might be a commissioned officer, privateer, bounty hunter, doctor, firearms dealer, lawyer, pharmacist, police officer, private investigator, mayor, governor and so on. This tag can be selected multiple times if appropriate.","page":63},
  "Backup": {"effect":"The character is part of an organization—like a police force—that they can call for immediate backup at any time.","page":63},
  "Black Market Access": {"effect":"The character knows how and where they can buy and sell hard—to-find and potentially illegal things.","page":63},
  "Chaotic": {"effect":"The character has been affected by the chaos lord Chthon.","page":63},
  "Convict": {"effect":"The character has been convicted of a crime, which is reflected on their record.","page":64},
  "Cursed": {"effect":"Willingly or not, the character is affiliated with Hell. This can open them up to all sorts of nefarious plots and plans.","page":64},
  "Deceased": {"effect":"The character is technically dead—although presumably still able to interact with the rest of the world in some way. They might be a vampire, a ghost, a zombie or even a brain floating in a jar.","page":64},
  "Dependents": {"effect":"The character has young children, elderly relatives or others who rely on them. They can't just abandon these people and must check on them and help care for them on a regular basis.","page":64},
  "Enemy": {"effect":"There's someone out there who has sworn to defeat the character. The enemy is of at least the same rank as the character and is obsessed with bringing them down. This tag can be taken multiple times, but it should be reserved for truly obsessed foes.","page":64},
  "Eternally Immortal": {"effect":"The character does not age and could theoretically live forever. If the character is killed, they can be brought back to life in the Activation Chamber found in the Exclusion, an Eternal base located beneath the South Pole. To make this happen, the Activation Chamber sacrifices the life of a random human anywhere on Earth.\n\nRestriction: For Eternals only.","page":64},
  "Extreme Appearance": {"effect":"The character looks very different than the average person (wherever they happen to be) and cannot easily hide their identity. When this tag appear sin origins in this chapter, it may give other useful information like whether an extreme appearance is common.","page":64},
  "Green Door": {"effect":"After being killed, the character can come back to life by passing through the Green Door, a portal that connects a part of the afterlife to Earth. This makes them effectively immortal.\n\nRestriction: For gamma mutates only.","page":64},
  "Headquarters": {"effect":"The character has a base, cave or lair they can use to recover from wounds, repair or store equipment, work on inventions and so on. The location can be public or secret, and it can be as humble as a tool shed or as elaborate as an underground complex or a Manhattan skyscraper.","page":64},
  "Heroic": {"effect":"The character acts heroically. They help people in need, and they do their best not to kill—even with people who might deserve it.\n\nRestriction: The character cannot also be Villainous.","page":64},
  "Hounded": {"effect":"The character is a member of a group of people who are persecuted for simply being themselves.","page":64},
  "Hunted": {"effect":"The character is hunted by the law for crimes they have supposedly (or actually) committed. If captured by the police, they may be arrested, tried for their crimes and potentially sent to jail.","page":64},
  "Imageless": {"effect":"The character casts no reflection, and their image cannot be captured by cameras.","page":64},
  "Immunity": {"effect":"The character is immune to the usual effects of something. This can be selected multiple times.","page":64},
  "Inhuman Genes": {"effect":"The character has latent Inhuman genes that cause them to develop super-powers when exposed to the Terrigen Mist.\n\nRestriction: For Inhumans only.","page":64},
  "Krakoan": {"effect":"As a mutant, the character is automatically a citizen of the island-nation of Krakoa and can travel to and from there freely. Also, if they are killed and the Five—a group of powerful mutants—are able to work together, the character can be resurrected into an identical new body with most of their memories intact. If killed in Otherworld, the character can still be resurrected, but they will be changed in unpredictable ways. Just how this might affect the character is up to the Narrator.\n\nRestriction: For mutants only.","page":64},
  "Lab Access": {"effect":"The character either owns or has access to a laboratory filled with the technical equipment, supplies and tools they need t by Humberto Ramos & Edgar Delgado for their work. This can be anything from a well-stocked high-school classroom to a forensics lab to an industrial site.","page":64},
  "Linguist": {"effect":"The character is fluent in a language other than their native tongue. This tag can be selected multiple times, once for each language.","page":65},
  "Lunar Transformation": {"effect":"On the three nights that the moon is at its fullest and while the moon is above the horizon, the character must transform into a werewolf and is ruled by their animal nature. They cannot help but hunt and attack any people or creatures they come across, no matter if they are friend or foe.\n\nRestriction: For werewolves only.","page":65},
  "Mahd Wy'ry": {"effect":"The character lives for so long that their accumulated memories have the potential to drive them insane. The only cure for this condition is to die and then be reborn with a restoration of their mind from a clean backup. This happens rarely, but the disease can progress quickly once it starts.\n\nRestriction: For Eternals only.","page":65},
  "Mentor": {"effect":"The character knows an older person they can ask for advice, even when it comes to having super-powers. This tag can be selected multiple times.","page":65},
  "Mute": {"effect":"The character cannot speak. Unless otherwise specified, they can use other means to communicate.","page":65},
  "Mysterious": {"effect":"The character does not entirely understand how or why they have powers. This can prove unsettling and perhaps even dangerous, or they can just take it in stride.","page":65},
  "Obligation": {"effect":"The character is responsible to certain people, places or organizations who rely on them. This tag can be selected multiple times, using many different categories. These include family, school, society, sports, work and so on.","page":65},
  "Poor": {"effect":"The character has little access to money and struggles to make ends meet. This can cause them all sorts of problems.","page":65},
  "Powerful": {"effect":"The character has access to the resources of their entire community. In most cases, they must be careful about how they use such resources so that they don't lose that access.","page":65},
  "Public Identity": {"effect":"The character's real identity is known to the public. This can make it easier for them to ask their friends and family—and even strangers—for help. Unfortunately, it also makes it easier for their enemies to find them and even to threaten those same friends and family.","page":65},
  "Radioactive": {"effect":"The character constantly emits low levels of some sort of radiation. This can be picked up by a Geiger counter.","page":65},
  "Rich": {"effect":"The character has access to plenty of money. If they want something normally and legally available to people, they can simply buy it.","page":65},
  "Secret Identity": {"effect":"The character's real identity is a secret to the public, and they must take precautions to maintain this status. This might help keep the people they care about safe from their enemies, but it can also cause strain in those same relationships.","page":65},
  "Signature Weapon": {"effect":"The character is known for owning and using a specific type of weapon, like Hawkeye's bow or Elektra's sai. This tag can be taken more than once, but each time must be with a different weapon.","page":65},
  "Sorcerous": {"effect":"The character has dedicated them self to the study of traditional magic, also known as sorcery.","page":65},
  "Streetwise": {"effect":"The character knows how things are handled on the street, who's in charge of various criminal enterprises and how to avoid issues with them.","page":65},
  "Supernatural": {"effect":"The character has powers that are magical or based on something magical.","page":65},
  "Villainous": {"effect":"The character is a villain, someone who cares little for the rights of others, up to and including their right to live.\n\nRestriction: The character cannot also be Heroic.","page":65},
  "Vision Issues": {"effect":"The character has trouble seeing that can range from partial to full blindness. This can also include color blindness, astigmatisms and being nearsighted or farsighted.","page":65},
  "Worshipped": {"effect":"The character is worshipped by others as a god.","page":65},
  "X-Gene": {"effect":"The character has mutant genes that cause them to develop super-powers.\n\nRestriction: For mutants only.","page":65},
  "Young": {"effect":"The character is a minor, under 18 years old. If possible, they must report in to their parents or guardians on a regular basis.","page":65},
};

